// Original icons retained for existing messages; v2 PNGs are the supplied assets, unchanged.
const icons: Record<string, string> = {
  "doc-v1.png": "",
  "image-v1.png": "",
  "alert-v1.png": "",
  "help-v1.png": "",
  "check-green-v2.png": "",
  "check-green-v1.png": "",
  "out-v3.png": "",
  "check-v1.png": "",
  "bag-v2.png": "",
  "in-v2.png": "",
  "out-v2.png": "",
  "bag.png": "",
  "in.png": "",
  "out.png": "",
};

export function handleLineIcon(pathname: string): Response {
  const encoded = icons[pathname.replace(/^\/line\/icons\//, "")];
  if (!encoded) return new Response("not found", { status: 404 });
  const bytes = Uint8Array.from(atob(encoded), (char) => char.charCodeAt(0));
  return new Response(bytes, {
    headers: { "content-type": "image/png", "cache-control": "public, max-age=86400" },
  });
}
